extends Sprite2D

var velocity: Vector2 = Vector2(200.0, -120.0)


func _ready() -> void:
	# Posiziona la navicella alle coordinate di partenza
	position = Vector2(150.0, 450.0)


func _process(delta: float) -> void:
	# Sposta la navicella sommando la velocita vettoriale scalata per il tempo
	position += velocity * delta
